#!/usr/bin/env bash
set -Eeuo pipefail
STATE_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/sway/mount"; mkdir -p -m 700 "$STATE_DIR"
exec 9>"$STATE_DIR/usb-format.lock"; flock -n 9 || { echo 'Another USB erase/reformat menu is open.'; exit 0; }
pause_terminal(){ echo; if [[ -r /dev/tty && -w /dev/tty ]]; then printf 'Press any key to close...' >/dev/tty; IFS= read -n1 -rs </dev/tty || true; echo >/dev/tty; fi; }
finish(){ s=$?; trap - EXIT; ((s==0||s==130)) || echo "USB operation stopped with exit status $s."; pause_terminal; exit "$s"; }
trap finish EXIT; trap 'exit 130' INT TERM HUP
need(){ local m=() c; for c in "$@"; do command -v "$c" >/dev/null || m+=("$c"); done; ((${#m[@]}==0)) || { echo "Unavailable; missing: ${m[*]}"; return 1; }; }
readv(){ IFS= read -r "$1" || exit 0; }
root_disk(){ local s; s="$(findmnt -rn -o SOURCE / 2>/dev/null||true)"; [[ -b $s ]] && lsblk -srnpo NAME,TYPE "$s"|awk '$2=="disk"{print $1;exit}' || true; }
identity(){ local d="$1"; printf '%s|%s|%s\n' "$(udevadm info -q property -n "$d" 2>/dev/null|sed -n 's/^ID_SERIAL=//p'|head -1)" "$(sudo blockdev --getsize64 "$d")" "$(lsblk -dnro MODEL "$d"|sed 's/[[:space:]]*$//')"; }
select_device(){ local a i x rd; while :; do mapfile -t R < <(lsblk -J -b -d -o PATH,TYPE,TRAN,RM,SIZE,VENDOR,MODEL,SERIAL|jq -r '.blockdevices[]|select(.type=="disk" and(.tran=="usb" or.rm==true or.rm==1))|[.path,(.size|tostring),(.vendor//""),(.model//""),(.serial//"")]|@base64'); echo; echo 'USB erase and reformat | Device'; echo; echo '[E] Exit'; ((${#R[@]}))||{ echo 'No removable USB disk found.'; return 1; }; for i in "${!R[@]}"; do x="$(base64 -d<<<"${R[$i]}")"; printf '[%d] %s  %s  %s %s  %s\n' "$((i+1))" "$(jq -r '.[0]'<<<"$x")" "$(numfmt --to=iec-i --suffix=B "$(jq -r '.[1]'<<<"$x")")" "$(jq -r '.[2]'<<<"$x")" "$(jq -r '.[3]'<<<"$x")" "$(jq -r '.[4]'<<<"$x")"; done; printf '\nSelect: '; readv a; [[ $a =~ ^[Ee]$ ]]&&exit 0; [[ $a =~ ^[0-9]+$ ]]&&((10#$a>=1&&10#$a<=${#R[@]}))||continue; x="$(base64 -d<<<"${R[$((10#$a-1))]}")"; DEVICE="$(jq -r '.[0]'<<<"$x")"; rd="$(root_disk)"; [[ -b $DEVICE && $DEVICE != "$rd" ]]||continue; DEVICE_ID="$(identity "$DEVICE")"; return; done; }
choose(){ local a; echo; echo 'USB erase and reformat | Purpose'; echo; echo '[E] Exit'; echo '[B] Back'; echo '[1] exFAT data drive (Windows, macOS, Linux; files over 4 GiB)'; echo '[2] FAT32 data/boot drive (widest compatibility; 4 GiB limit)'; echo '[3] NTFS data drive (Windows-focused; macOS normally read-only)'; echo '[4] ext4 data drive (Linux-focused)'; echo '[5] Write an ISO image to the whole USB'; echo '[6] Blank GPT disk'; echo '[7] Full zero overwrite, then exFAT'; printf '\nSelect: '; readv a; case "$a" in [Ee])exit 0;;[Bb])return 2;;1|2|3|4|5|6|7) ACTION=$a;;*)return 2;;esac; }
label(){ local n=$1 a; while :; do printf 'Volume label [USB] (B=Back, E=Exit; max %s): ' "$n"; readv a; case "${a,,}" in e)exit 0;;b)return 2;;esac; LABEL="${a:-USB}"; [[ $LABEL =~ ^[A-Za-z0-9._\ -]+$ ]]&&(( ${#LABEL}<=n ))&&return; echo 'Invalid label.'; done; }
iso(){ local a x is us; while :; do printf 'ISO path (B=Back, E=Exit): '; readv a; case "${a,,}" in e)exit 0;;b)return 2;;esac; [[ $a == '~/'* ]]&&x="$HOME/${a:2}"||x=$a; [[ -f $x && -r $x && ${x,,} == *.iso ]]||continue; ISO="$(readlink -f -- "$x")"; is="$(stat -c%s -- "$ISO")"; us="$(sudo blockdev --getsize64 "$DEVICE")"; ((is<=us))&&return; echo 'ISO is larger than USB.'; done; }
mounts(){ local n; while read -r n; do findmnt -rn -S "$n" -o TARGET 2>/dev/null||true; done < <(lsblk -rnpo NAME "$DEVICE"); }
unmount_all(){ mapfile -t M < <(mounts|awk 'NF&&!s[$0]++'); for((i=${#M[@]}-1;i>=0;i--));do sudo umount -- "${M[$i]}";done; [[ -z $(mounts) ]]; }
confirm(){ local x; [[ $(identity "$DEVICE") == "$DEVICE_ID" ]]||return 1; echo; echo 'FINAL REVIEW'; echo "Device: $DEVICE"; lsblk -o NAME,SIZE,TYPE,PARTTYPENAME,PARTTYPE,FSTYPE,LABEL,MOUNTPOINTS "$DEVICE"; echo "Action: $DESC"; [[ -z ${ISO:-} ]]||echo "ISO: $ISO"; echo; echo 'ALL DATA ON THIS USB WILL BE DESTROYED.'; printf 'Type %s: ' "$DEVICE"; readv x; [[ $x == "$DEVICE" ]]||return 2; printf 'Type ERASE: '; readv x; [[ $x == ERASE ]]||return 2; }
wipe(){ mapfile -t N < <(lsblk -rnpo NAME,TYPE "$DEVICE"|awk '$2=="part"{print $1}'); for n in "${N[@]}";do sudo wipefs -af "$n";done; sudo wipefs -af "$DEVICE"; sudo blockdev --rereadpt "$DEVICE" 2>/dev/null||true; sudo udevadm settle; }
mkpart(){ local p end=$((SECONDS+10)); sudo parted -s -a optimal "$DEVICE" mklabel gpt mkpart primary 1MiB 100%; sudo partprobe "$DEVICE"; sudo udevadm settle; while((SECONDS<end));do p="$(lsblk -rnpo NAME,TYPE "$DEVICE"|awk '$2=="part"{print $1;exit}')"; [[ -b $p ]]&&{ printf '%s\n' "$p";return;};sleep .1;done;return 1; }
set_type(){ local kind=$1 p=$2 expected actual; case $kind in exfat|fat32|ntfs) sudo parted -s "$DEVICE" set 1 msftdata on; expected=EBD0A0A2-B9E5-4433-87C0-68B6B72699C7;;ext4) expected=0FC63DAF-8483-4772-8E79-3D69D8477DE4;;esac; sudo partprobe "$DEVICE"; sudo udevadm settle; actual="$(lsblk -dnro PARTTYPE "$p"|tr '[:lower:]' '[:upper:]')"; [[ $actual == "$expected" ]]||{ echo "Partition type verification failed: $actual" >&2;return 1;}; }
format(){ local k=$1 p e a; wipe; p="$(mkpart)"; sudo wipefs -af "$p"; set_type "$k" "$p"; case $k in exfat)sudo mkfs.exfat -F -C -n "$LABEL" "$p";e=exfat;;fat32)sudo mkfs.vfat -F32 -n "$LABEL" "$p";e=vfat;;ntfs)sudo mkfs.ntfs -F -L "$LABEL" "$p";e=ntfs;;ext4)sudo mkfs.ext4 -F -L "$LABEL" "$p";e=ext4;;esac; sync;sudo udevadm settle;a="$(sudo blkid -p -s TYPE -o value "$p" 2>/dev/null||true)";[[ $a == "$e" ]]; }
need lsblk findmnt jq numfmt base64 flock udevadm sudo readlink stat blockdev blkid awk sed sha256sum head parted partprobe wipefs || exit 1
while :;do select_device||exit 0; s=0;choose||s=$?;((s==2))&&continue;unset ISO LABEL;case $ACTION in 1)need mkfs.exfat||continue;label 15||continue;DESC="GPT Microsoft Basic Data + exFAT $LABEL";;2)need mkfs.vfat||continue;label 11||continue;DESC="GPT Microsoft Basic Data + FAT32 $LABEL";;3)need mkfs.ntfs||continue;label 32||continue;DESC="GPT Microsoft Basic Data + NTFS $LABEL";;4)need mkfs.ext4||continue;label 16||continue;DESC="GPT Linux filesystem + ext4 $LABEL";;5)need dd||continue;iso||continue;DESC='Write ISO byte-for-byte';;6)need sfdisk||continue;DESC='Empty GPT disk';;7)need dd mkfs.exfat||continue;label 15||continue;DESC="Zero then GPT Microsoft Basic Data + exFAT $LABEL";;esac;c=0;confirm||c=$?;((c==2))&&continue;((c==0))||exit "$c";unmount_all;case $ACTION in 1)format exfat;;2)format fat32;;3)format ntfs;;4)format ext4;;5)wipe;sudo dd if="$ISO" of="$DEVICE" bs=16M status=progress conv=fsync;sudo partprobe "$DEVICE"||true;sudo udevadm settle;;6)wipe;sudo parted -s "$DEVICE" mklabel gpt;sudo partprobe "$DEVICE";sudo udevadm settle;sudo sfdisk --json "$DEVICE"|jq -e '.partitiontable.label=="gpt" and(.partitiontable.partitions|length==0)' >/dev/null;;7)sudo dd if=/dev/zero of="$DEVICE" bs=16M status=progress conv=fsync;format exfat;;esac;echo;echo 'Completed successfully. Current device layout:';lsblk -o NAME,SIZE,TYPE,PARTTYPENAME,PARTTYPE,FSTYPE,LABEL,MOUNTPOINTS "$DEVICE";exit 0;done
